def stop(self, pid: Optional[str] = None):
    """
    停止插件服务
    :param pid: 插件ID，为空停止所有插件
    """
    # 停止插件
    if pid:
        logger.info(f"正在停止插件 {pid}...")
        plugin_obj = self._running_plugins.get(pid)
        if not plugin_obj:
            # 指定插件可能在上次加载时已导入模块但初始化失败，此时不会进入运行态列表。
            # 仍需继续清理类缓存和 sys.modules，避免后续热重载反复复用旧模块。
            logger.debug(f"插件 {pid} 不存在或未加载")
            plugins = {}
        else:
            plugins = {pid: plugin_obj}
    else:
        logger.info("正在停止所有插件...")
        plugins = self._running_plugins
    for plugin_id, plugin in plugins.items():
        eventmanager.disable_event_handler(type(plugin))
        self.__stop_plugin(plugin)
    # 清空对象
    if pid:
        # 清空指定插件
        self._plugins.pop(pid, None)
        self._running_plugins.pop(pid, None)
        # 清除插件模块缓存，包括所有子模块
        self._clear_plugin_modules(pid)
    else:
        # 清空
        self._plugins = {}
        self._running_plugins = {}
        # 清除所有插件模块缓存
        self._clear_plugin_modules()
    self.clear_plugin_agent_tools_cache()
    logger.info("插件停止完成")

def __stop_plugin(plugin: Any):
    """
    停止插件
    :param plugin: 插件实例
    """
    try:
        # 关闭数据库
        if hasattr(plugin, "close"):
            plugin.close()
        # 关闭插件
        if hasattr(plugin, "stop_service"):
            plugin.stop_service()
    except Exception as e:
        logger.warn(f"停止插件 {plugin.get_name()} 时发生错误: {str(e)}")

def get_plugin_remotes(self, pid: Optional[str] = None) -> List[Dict[str, Any]]:
    """
    获取插件联邦组件列表
    """
    remotes = []
    # 创建字典快照避免并发修改
    running_plugins_snapshot = dict(self._running_plugins)
    for plugin_id, plugin in running_plugins_snapshot.items():
        if pid and pid != plugin_id:
            continue
        if hasattr(plugin, "get_render_mode"):
            render_mode, dist_path = plugin.get_render_mode()
            if render_mode != "vue":
                continue
            remotes.append({
                "id": plugin_id,
                "url": self.get_plugin_remote_entry(plugin_id, dist_path),
                "name": plugin.plugin_name,
            })
    return remotes

def _rename_federation_assets(dist_dir: Path, original_class_name: str, clone_class_name: str):
    """
    重命名联邦插件的资源文件，避免文件名冲突
    """
    try:
        # 查找包含原类名的文件并重命名
        for file_path in dist_dir.glob("*"):
            if not file_path.is_file():
                continue

            file_name = file_path.name
            # 如果文件名包含原类名，则重命名
            if original_class_name.lower() in file_name.lower():
                new_name = file_name.replace(
                    original_class_name.lower(),
                    clone_class_name.lower()
                )
                new_path = file_path.parent / new_name

                # 避免重命名冲突
                if not new_path.exists():
                    file_path.rename(new_path)
                    logger.debug(f"重命名联邦插件文件：{file_name} -> {new_name}")

    except Exception as e:
        # 重命名失败不影响整体流程
        logger.warning(f"重命名联邦插件资源文件失败：{str(e)}")

def plugin_form(
    plugin_id: str, _: User = Depends(get_current_active_superuser)
) -> dict:
    """
    根据插件ID获取插件配置表单或Vue组件URL
    """
    plugin_manager = PluginManager()
    plugin_instance = plugin_manager.running_plugins.get(plugin_id)
    if not plugin_instance:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"插件 {plugin_id} 不存在或未加载",
        )

    # 渲染模式
    render_mode, _ = plugin_instance.get_render_mode()
    try:
        conf, model = plugin_instance.get_form()
        stored_config = plugin_manager.get_plugin_config(plugin_id)
        # Merge stored config with defaults so all keys exist for v-show evaluation
        merged_model = {**model, **(stored_config or {})}
        return {
            "render_mode": render_mode,
            "conf": conf,
            "model": merged_model,
        }
    except Exception as e:
        logger.error(f"插件 {plugin_id} 调用方法 get_form 出错: {str(e)}")
    return {}

async def install(
    plugin_id: str,
    repo_url: Optional[str] = "",
    release_version: Optional[str] = None,
    force: Optional[bool] = False,
    _: User = Depends(get_current_active_superuser_async),
) -> Any:
    """
    安装插件
    """
    # 已安装插件
    install_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []
    # 首先检查插件是否已经存在，并且是否强制安装，否则只进行安装统计
    plugin_helper = PluginHelper()
    if not force and plugin_id in PluginManager().get_plugin_ids():
        if repo_url:
            compatible_message = await plugin_helper.async_get_plugin_system_version_check_message(
                plugin_id, repo_url
            )
            if compatible_message:
                return schemas.Response(success=False, message=compatible_message)
        await MoviePilotServerHelper.async_install_plugin_reg(plugin_id=plugin_id, repo_url=repo_url)
    else:
        # 插件不存在或需要强制安装，下载安装并注册插件
        if repo_url:
            state, msg = await plugin_helper.async_install(
                pid=plugin_id, repo_url=repo_url, release_version=release_version, force_install=force
            )
            # 安装失败则直接响应
            if not state:
                return schemas.Response(success=False, message=msg)
            await MoviePilotServerHelper.async_install_plugin_reg(plugin_id=plugin_id, repo_url=repo_url)
        else:
            # repo_url 为空时，也直接响应
            return schemas.Response(
                success=False, message="没有传入仓库地址，无法正确安装插件，请检查配置"
            )
    # 安装插件
    if plugin_id not in install_plugins:
        install_plugins.append(plugin_id)
        # 保存设置
        await SystemConfigOper().async_set(
            SystemConfigKey.UserInstalledPlugins, install_plugins
        )
    # 重新加载插件
    await run_in_threadpool(reload_plugin, plugin_id)
    return schemas.Response(success=True)

